@RunWith(RobolectricTestRunner::class) @Config(sdk=[34])
class ResolutionStorageRoomTest {
 private val context:Context=ApplicationProvider.getApplicationContext();private val handles=mutableListOf<CycleCareDatabase>();private val names=mutableListOf<String>()
 private fun open():CycleCareDatabase{val name="outbox-${UUID.randomUUID()}";names+=name;return Room.databaseBuilder(context,CycleCareDatabase::class.java,name).allowMainThreadQueries().build().also{handles+=it;RustEnrollmentStage.schema(it.openHelper.writableDatabase);RustEnrollmentStage.senderSchema(it.openHelper.writableDatabase);val sql=it.openHelper.writableDatabase;sql.execSQL("CREATE TABLE IF NOT EXISTS rust_float_bits(dateString TEXT NOT NULL PRIMARY KEY,normalizedHash TEXT NOT NULL,bbtBits INTEGER NOT NULL,sleepBits INTEGER NOT NULL)");for(event in listOf("INSERT","UPDATE","DELETE")){val ref=if(event=="INSERT")"NEW.dateString"else"OLD.dateString";sql.execSQL("CREATE TRIGGER IF NOT EXISTS remote_float_${event.lowercase()} AFTER $event ON cycle_day_logs BEGIN DELETE FROM rust_float_bits WHERE dateString=$ref; END")}}}
 @After fun close(){handles.forEach{it.close()};names.forEach{context.deleteDatabase(it)}}
 private fun entry(base:Long=7,attempts:Int=2)=HealthSyncOutboxEntry("owner","op","2026-10-01","UPSERT",base,17,"synthetic 🌸/\n",HealthSyncPayloadCodec.hash("synthetic 🌸/\n"),3,attempts,77,"OLD_ERROR","OLD_RECEIPT",45)
 private fun seed(db:CycleCareDatabase,e:HealthSyncOutboxEntry,server:Long=3,revision:Boolean=true){db.runInTransaction{val s=db.openHelper.writableDatabase;if(revision)s.execSQL("INSERT INTO health_sync_revisions(ownerId,recordId,revision,payloadHash,tombstone,updatedAt,serverRevision) VALUES(?,?,?,?,?,?,?)",arrayOf<Any>(e.ownerId,e.recordId,99,"KEEP_HASH",1,987,server));for(row in listOf(e,e.copy(operationId="sibling",revision=18),e.copy(operationId="different-base",baseRevision=e.baseRevision xor 1L),e.copy(operationId="other-record",recordId="2026-10-02"),e.copy(operationId="other-owner",ownerId="other"))){s.execSQL("INSERT INTO health_sync_outbox VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)",arrayOf<Any?>(row.ownerId,row.operationId,row.recordId,row.kind,row.baseRevision,row.revision,row.payloadJson,row.payloadHash,row.consentGeneration,row.attempts,row.nextAttemptAt,row.lastError,row.serverReceipt,row.serverRevision))}}}
 private fun snapshot(db:CycleCareDatabase):List<List<String?>>{val out=mutableListOf<List<String?>>();for(table in listOf("rust_float_bits","cycle_day_logs","onboarding_profiles","cycle_settings","health_sync_revisions","health_sync_outbox","health_sync_conflicts","health_sync_cursors")){out+=listOf(table);db.openHelper.writableDatabase.query("SELECT * FROM $table ORDER BY 1,2").use{c->while(c.moveToNext())out+=(0 until c.columnCount).map{if(c.isNull(it))null else c.getString(it)}}};return out}


 private fun log(id:String="2026-10-01")=CycleDayLog(id,flowLevel="LIGHT",notes="synthetic 🌸/\n",bbtCelsius=Float.fromBits(Int.MIN_VALUE),sleepHours=Float.fromBits(1))
 private fun initial(db:CycleCareDatabase){db.runInTransaction{val sql=db.openHelper.writableDatabase;RustDomainRows.write(sql,"settings",RustDomainRows.Row.Settings(CycleSettings(isAppLockEnabled=true,lockTimeoutMinutes=19,lutealPhaseDays=17,isPregnancyMode=true,pregnancyDueDate="KEEP",remindDailyLog=true)));RustDomainRows.write(sql,"profile",RustDomainRows.Row.Profile(OnboardingProfile(completedAtTimestamp=44,lastPeriodEndDateString="KEEP_END",typicalEnergy="KEEP_ENERGY",hasCompletedDeepBaseline=true)));RustDomainRows.write(sql,"2026-10-01",RustDomainRows.Row.Log(log()))}}
 private fun payload(record:String):String=when(record){"settings"->HealthSyncPayloadCodec.settingsPayload(CycleSettings(averageCycleLength=33));"profile"->HealthSyncPayloadCodec.profilePayload(OnboardingProfile(completedAtTimestamp=55,selectedGoalsCsv="remote"));else->HealthSyncPayloadCodec.logPayload(log(record))}
 private fun setup(db:CycleCareDatabase,record:String="2026-10-01",local:Long=7,remote:Long=9,tombstone:Boolean=false,priorTombstone:Boolean=false,present:Boolean=true,localConflict:Long=local,localPayload:String?=payload(record),remotePayload:String?=if(tombstone)null else payload(record)){
  initial(db);val s=db.openHelper.writableDatabase
  if(present)s.execSQL("INSERT INTO health_sync_revisions VALUES(?,?,?,?,?,?,?)",arrayOf<Any?>("owner",record,local,HealthSyncPayloadCodec.hash(localPayload),if(priorTombstone)1 else 0,44,99))
  s.execSQL("INSERT INTO health_sync_conflicts VALUES(?,?,?,?,?,?,?,?,?,?,NULL,NULL)",arrayOf<Any?>("owner",record,"op",localConflict,localPayload,if(priorTombstone)"DELETE"else"UPSERT",remote,remotePayload,if(tombstone)1 else 0,55))
  for((op,rev)in listOf("old" to Long.MIN_VALUE,"same" to local,"future" to Long.MAX_VALUE)){s.execSQL("INSERT INTO health_sync_outbox VALUES(?,?,?,?,?,?,?,?,?,0,0,NULL,NULL,NULL)",arrayOf<Any?>("owner",op,record,"UPSERT",3,rev,"keep",HealthSyncPayloadCodec.hash("keep"),2))}
  s.execSQL("INSERT INTO health_sync_outbox VALUES('other','other',?,'UPSERT',3,1,'keep','hash',2,0,0,NULL,NULL,NULL)",arrayOf(record))
 }
 private fun apply(db:CycleCareDatabase,native:Boolean,record:String="2026-10-01",retain:Boolean=false,child:String="child",now:Long=999,generation:Long=3){db.runInTransaction{val s=db.openHelper.writableDatabase;if(native)RustResolutionStorage.apply(s,"owner",record,retain,child,now,generation)else RustConflictRows.apply(s,"owner",record,retain,child,now,generation)}}
 @Test fun fullDatabaseExactBothBranchesSignedRevisionsMergeFloatAndTombstones(){RustTrackNative.warmUp();for(record in listOf("settings","profile","2026-10-01"))for(local in listOf(Long.MIN_VALUE,0L,Long.MAX_VALUE-1))for(retain in listOf(false,true))for(tombstone in listOf(false,true)){
  if(retain&&tombstone)continue
  val a=open();val b=open();for(db in listOf(a,b))setup(db,record,local,if(retain)0 else Long.MAX_VALUE,tombstone,priorTombstone=retain)
  apply(a,false,record,retain,now=Long.MAX_VALUE);apply(b,true,record,retain,now=Long.MAX_VALUE);assertEquals(snapshot(a),snapshot(b));val before=snapshot(b);apply(b,true,record,retain);assertEquals(before,snapshot(b));if(!retain&&record=="settings"){val v=(RustDomainRows.read(b.openHelper.writableDatabase,record)as RustDomainRows.Row.Settings).value;assertTrue(v.isAppLockEnabled);assertEquals(19,v.lockTimeoutMinutes)}
 }}
 @Test fun missingStaleHashAbsentAndResolvedNoOpsExactOriginal(){RustTrackNative.warmUp();for(case in listOf("missing","resolved","revision","hash","absentNonzero","absentRetain","absentAccept")){val a=open();val b=open();for(db in listOf(a,b)){setup(db,present=!case.startsWith("absent"),localConflict=if(case.startsWith("absent"))if(case=="absentNonzero")1 else 0 else 7);val s=db.openHelper.writableDatabase;when(case){"missing"->s.execSQL("DELETE FROM health_sync_conflicts");"resolved"->s.execSQL("UPDATE health_sync_conflicts SET resolvedAt=1,resolution='OLD'");"revision"->s.execSQL("UPDATE health_sync_revisions SET revision=8");"hash"->s.execSQL("UPDATE health_sync_revisions SET payloadHash=NULL")}};val before=snapshot(b);apply(a,false,retain=case=="absentRetain");apply(b,true,retain=case=="absentRetain");assertEquals(snapshot(a),snapshot(b));if(case!="absentAccept")assertEquals(before,snapshot(b))}}
 @Test fun exactRejectionOverflowChildAndParseOrderNoEffects(){RustTrackNative.warmUp();for(case in listOf("overflow","remoteNegative","remoteZero","retainTombstone","childBlank","childLong","remoteMissing","payloadInvalid","tombstonePayload"))for(native in listOf(false,true)){val db=open();val retain=case in listOf("retainTombstone","childBlank","childLong");setup(db,local=if(case=="overflow")Long.MAX_VALUE else 7,remote=if(case in listOf("overflow","remoteNegative"))-1 else if(case=="remoteZero")0 else 9,tombstone=case in listOf("retainTombstone","tombstonePayload"),remotePayload=when(case){"remoteMissing"->null;"payloadInvalid","tombstonePayload"->"invalid";else->payload("2026-10-01")});val before=snapshot(db);val child=if(case=="childBlank")"  "else if(case=="childLong")"🌸".repeat(65)else"child";val e=runCatching{apply(db,native,retain=retain,child=child)}.exceptionOrNull();assertNotNull(case,e);if(case=="overflow"){assertTrue(e is ArithmeticException);assertEquals("long overflow",e?.message)};if(case in listOf("remoteNegative","remoteZero","retainTombstone")){assertTrue(e is ConflictRejected);assertEquals(if(case=="retainTombstone")"keep_local_unavailable_server_tombstone"else"remote_record_missing_accept_unavailable",e?.message)};assertEquals(before,snapshot(db))};val db=open();val before=snapshot(db);for(native in listOf(false,true))for((now,generation)in listOf(-1L to 0L,0L to -1L)){assertTrue(runCatching{apply(db,native,now=now,generation=generation)}.exceptionOrNull()is IllegalArgumentException);assertEquals(before,snapshot(db))}}
 @Test fun allBeforeAfterEffectsRollbackThenRetryOriginalEquality(){RustTrackNative.warmUp();for(retain in listOf(false,true))for(timing in listOf("BEFORE","AFTER"))for(point in if(retain)listOf("delete","revision","outbox","resolve")else listOf("domain","bits","delete","revision","resolve")){val a=open();val b=open();setup(a);setup(b);val s=b.openHelper.writableDatabase;val before=snapshot(b);val clause=when(point){"domain"->"UPDATE ON cycle_day_logs";"bits"->"INSERT ON rust_float_bits";"delete"->"DELETE ON health_sync_outbox";"revision"->"INSERT ON health_sync_revisions";"outbox"->"INSERT ON health_sync_outbox";else->"UPDATE ON health_sync_conflicts"};s.execSQL("CREATE TRIGGER fault $timing $clause BEGIN SELECT RAISE(ABORT,'resolution fault'); END");assertNotNull("$retain/$timing/$point",runCatching{apply(b,true,retain=retain)}.exceptionOrNull());assertEquals(before,snapshot(b));s.execSQL("DROP TRIGGER fault");apply(b,true,retain=retain);apply(a,false,retain=retain);assertEquals(snapshot(a),snapshot(b))}}
 @Test fun retainedNullPayloadKindTombstoneUtf16ChildAndGenerationBoundaries(){RustTrackNative.warmUp();for(priorTombstone in listOf(false,true))for(localPayload in listOf<String?>(null,"synthetic 🌸/\n\u0000tail"))for(remote in listOf(0L,Long.MAX_VALUE)){val a=open();val b=open();for(db in listOf(a,b))setup(db,priorTombstone=priorTombstone,localPayload=localPayload,remote=remote);apply(a,false,retain=true,child="🌸".repeat(64),generation=Long.MAX_VALUE);apply(b,true,retain=true,child="🌸".repeat(64),generation=Long.MAX_VALUE);assertEquals(snapshot(a),snapshot(b));b.openHelper.writableDatabase.query("SELECT payloadJson,payloadHash,kind,consentGeneration FROM health_sync_outbox WHERE operationId=?",arrayOf("🌸".repeat(64))).use{assertTrue(it.moveToFirst());assertEquals(localPayload,if(it.isNull(0))null else it.getString(0));assertEquals(HealthSyncPayloadCodec.hash(localPayload),it.getString(1));assertEquals(if(priorTombstone)"DELETE"else"UPSERT",it.getString(2));assertEquals(Long.MAX_VALUE,it.getLong(3))}}}
 @Test fun privateSessionWrongBranchNextOrderThreadClosedAndReentry(){
  RustTrackNative.warmUp();val db=open();setup(db);val sql=db.openHelper.writableDatabase;val before=snapshot(db);val field=RustResolutionStorage::class.java.getDeclaredField("entered").apply{isAccessible=true};@Suppress("UNCHECKED_CAST")val entered=field.get(RustResolutionStorage)as ThreadLocal<Boolean>;val cls=Class.forName("com.cyclecare.app.data.local.rust.RustResolutionStorage\$Session");val ctor=cls.declaredConstructors.single().apply{isAccessible=true}
  fun call(session:Any,name:String,vararg args:Any):Any?{val m=cls.declaredMethods.single{it.name==name}.apply{isAccessible=true};return try{m.invoke(session,*args)}catch(e:java.lang.reflect.InvocationTargetException){throw e.cause!!}}
  val end=runCatching{db.runInTransaction{entered.set(true);val session=ctor.newInstance(sql,"owner","2026-10-01",false,"child",999L,3L);try{for(name in listOf("metadata","delete","domain","resolve"))assertNotNull(runCatching{call(session,name)}.exceptionOrNull());assertNotNull(runCatching{RustResolutionStorage.apply(sql,"owner","2026-10-01",false,"child",999,3)}.exceptionOrNull());val error=java.util.concurrent.atomic.AtomicReference<Throwable>();val t=Thread{try{call(session,"ready")}catch(e:Throwable){error.set(e)}};t.start();t.join(5000);assertFalse(t.isAlive);assertTrue(error.get()is IllegalStateException);call(session,"ready");call(session,"metadata");assertNotNull(runCatching{call(session,"skip")}.exceptionOrNull());assertNotNull(runCatching{call(session,"prepare",8L,false)}.exceptionOrNull());assertEquals(true,call(session,"hashMatches"));assertNotNull(runCatching{call(session,"hashMatches")}.exceptionOrNull());for(args in listOf(arrayOf<Any>(9L,false),arrayOf<Any>(8L,true)))assertNotNull(runCatching{call(session,"prepare",*args)}.exceptionOrNull());assertNotNull(runCatching{call(session,"skip")}.exceptionOrNull());call(session,"prepare",8L,false);assertNotNull(runCatching{call(session,"delete")}.exceptionOrNull());call(session,"domain");call(session,"delete");assertNotNull(runCatching{call(session,"revision",9L)}.exceptionOrNull());call(session,"revision",8L);assertNotNull(runCatching{call(session,"outbox")}.exceptionOrNull());call(session,"resolve");assertNotNull(runCatching{call(session,"outcome",0)}.exceptionOrNull());call(session,"outcome",1);call(session,"close");assertNotNull(runCatching{call(session,"outcome",1)}.exceptionOrNull());throw IllegalStateException("adversarial rollback")}finally{call(session,"close");entered.remove()}}}.exceptionOrNull();assertEquals("adversarial rollback",end?.message);assertEquals(before,snapshot(db))
 }
 @Test fun actualHostSameDatabaseOriginalRollbackControlIdentityAndNoOp()=runBlocking{
  RustTrackNative.warmUp();val db=open();setup(db,record="settings");val prefs=AuthPreferences(context,context.getSharedPreferences("resolution-${UUID.randomUUID()}",Context.MODE_PRIVATE),true).apply{userId="owner"};val h=RustBoundRoomHost(prefs);val t=(h.publish(null,db,prefs.rustOperationSnapshot())as RustBoundRoomHost.Result.Value).value;val before=snapshot(db);var expected:List<List<String?>>?=null;val control=runCatching{db.runInTransaction{RustConflictRows.apply(db.openHelper.writableDatabase,"owner","settings",false,"child",999,prefs.healthConsentGeneration);expected=snapshot(db);throw IllegalStateException("original rollback")}}.exceptionOrNull();assertEquals("original rollback",control?.message);assertEquals(before,snapshot(db))
  suspend fun call()=withContext(Dispatchers.IO){h.resolveConflict(t,"settings",false,"child",999)}
  assertTrue(call()is RustBoundRoomHost.Result.Value);assertEquals(expected,snapshot(db));assertTrue(call()is RustBoundRoomHost.Result.Value);assertEquals(expected,snapshot(db));prefs.userId="other";assertEquals(RustBoundRoomHost.Result.Stale,call());assertEquals(expected,snapshot(db))
 }
